Definition init_statics0 (M : word -> option byte) : Prop :=
     (forall a : word, 0xf8c58 <= bv_unsigned a < 0xf9008 -> M a = None)
  /\ (forall a : word, RVMLOCKC <= bv_unsigned a < RVMLOCKC + 4 -> M a = None)      (* [comment removed for export] *)
